create or replace function public.queue_deep_scan(p_extension_id text,p_name text,p_display_name text,p_publisher text,p_description text,p_registry text,p_version text,p_requester_hash text,p_icon_url text default '',p_publisher_verified boolean default false,p_installs bigint default 0,p_rating numeric default 0) returns public.scan_jobs language plpgsql security definer set search_path=public as $$ declare job public.scan_jobs; recent_count integer; begin if p_extension_id !~ '^[A-Za-z0-9_-]+\.[A-Za-z0-9_.-]+$' or length(p_version)>80 then raise exception 'Invalid extension identity'; end if; if p_registry not in ('vs-marketplace','openvsx') then raise exception 'Unsupported registry'; end if; select count(*) into recent_count from public.scan_jobs where requester_hash=p_requester_hash and created_at>now()-interval '1 hour'; if recent_count>=3 then raise exception 'Deep Scan limit reached. Try again after one hour'; end if; select * into job from public.scan_jobs where extension_id=p_extension_id and version=p_version and profile='deep' and status in ('queued','running') limit 1; if found then return job; end if; insert into public.extensions(id,name,display_name,publisher,description,registry,publisher_verified,installs,rating,icon_url,updated_at) values(p_extension_id,left(p_name,160),left(p_display_name,200),left(p_publisher,160),left(p_description,2000),p_registry,p_publisher_verified,greatest(p_installs,0),greatest(p_rating,0),left(p_icon_url,2000),now()) on conflict(id) do update set display_name=excluded.display_name,description=excluded.description,publisher_verified=excluded.publisher_verified,installs=excluded.installs,rating=excluded.rating,icon_url=excluded.icon_url,updated_at=now(); update public.extension_versions set is_latest=false where extension_id=p_extension_id and version<>p_version; insert into public.extension_versions(extension_id,version,registry,is_latest,scan_state) values(p_extension_id,p_version,p_registry,true,'queued') on conflict(extension_id,version) do update set scan_state='queued'; insert into public.scan_jobs(extension_id,version,profile,requester_hash,requested_by) values(p_extension_id,p_version,'deep',p_requester_hash,auth.uid()) returning * into job; return job; end $$; revoke all on function public.queue_deep_scan(text,text,text,text,text,text,text,text,text,boolean,bigint,numeric) from public; grant execute on function public.queue_deep_scan(text,text,text,text,text,text,text,text,text,boolean,bigint,numeric) to anon,authenticated;
create or replace function public.submit_design_partner(p_name text,p_email text,p_company text,p_team_size text,p_process text,p_extension_count text,p_requester_hash text) returns uuid language plpgsql security definer set search_path=public as $$ declare lead_id uuid; recent_count integer; begin if p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or trim(p_name)='' or trim(p_company)='' then raise exception 'Name, company, and a valid work email are required'; end if; select count(*) into recent_count from public.product_events where anonymous_id=p_requester_hash and name='design_partner_submitted' and created_at>now()-interval '1 day'; if recent_count>=3 then raise exception 'Submission limit reached'; end if; insert into public.design_partner_leads(user_id,name,work_email,company,team_size,current_process,extension_count) values(auth.uid(),left(trim(p_name),100),left(lower(trim(p_email)),180),left(trim(p_company),140),left(p_team_size,50),left(p_process,2000),left(p_extension_count,50)) returning id into lead_id; insert into public.product_events(user_id,anonymous_id,name,properties) values(auth.uid(),p_requester_hash,'design_partner_submitted',jsonb_build_object('lead_id',lead_id)); return lead_id; end $$; revoke all on function public.submit_design_partner(text,text,text,text,text,text,text) from public; grant execute on function public.submit_design_partner(text,text,text,text,text,text,text) to anon,authenticated;;
